// @ts-nocheck
export function buildSharedErrorRoutesSource(): string {
  return [
    "// Generated by OpenShapeForge Service Compiler.",
    "// Do not edit manually.",
    "",
    'import type { Field, LocalizedText } from "@/generated/compiler/field-contract";',
    'import type { WorkflowNodeHandle } from "../../shared/types";',
    "",
    "export type GeneratedEntityErrorRouteOption = {",
    "  id: string;",
    "  handleId: string;",
    "  label: Required<Pick<LocalizedText, \"en\" | \"nl\">>;",
    "  description: Required<Pick<LocalizedText, \"en\" | \"nl\">>;",
    "  matchCodes: readonly string[];",
    "  matchStatusCodes: readonly number[];",
    "};",
    "",
    "export type GeneratedEntityErrorRouteConfig = Record<string, boolean>;",
    "",
    "const DEFAULT_SUCCESS_HANDLE_ID = \"default\";",
    "const DEFAULT_SUCCESS_HANDLE_LABEL = \"Volgende\";",
    "const DEFAULT_ERROR_HANDLE_ID = \"error\";",
    "const DEFAULT_ERROR_HANDLE_LABEL = \"Fout\";",
    "const LIST_NONE_HANDLE_ID = \"none\";",
    "const LIST_ONE_HANDLE_ID = \"one\";",
    "const LIST_MANY_HANDLE_ID = \"many\";",
    "",
    "function normalizeSelection(",
    "  value: unknown,",
    "  supportedIds: readonly string[],",
    "): GeneratedEntityErrorRouteConfig {",
    "  const supported = new Set(supportedIds);",
    "  const result: GeneratedEntityErrorRouteConfig = {};",
    "",
    "  if (Array.isArray(value)) {",
    "    for (const entry of value) {",
    "      if (typeof entry !== \"string\") {",
    "        continue;",
    "      }",
    "      const trimmed = entry.trim();",
    "      if (trimmed && supported.has(trimmed)) {",
    "        result[trimmed] = true;",
    "      }",
    "    }",
    "    return result;",
    "  }",
    "",
    "  if (value && typeof value === \"object\") {",
    "    const record = value as Record<string, unknown>;",
    "    for (const [key, enabled] of Object.entries(record)) {",
    "      const trimmed = typeof key === \"string\" ? key.trim() : \"\";",
    "      if (trimmed && supported.has(trimmed) && enabled === true) {",
    "        result[trimmed] = true;",
    "      }",
    "    }",
    "    return result;",
    "  }",
    "",
    "  return result;",
    "}",
    "",
    "/**",
    " * Builds the designer field the workflow inspector uses to toggle error routes.",
    " * Uses the standard object + boolean children pattern so no custom component",
    " * is needed — the renderer's existing Checkbox primitive produces the UX.",
    " */",
    "export function buildGeneratedEntityErrorRouteField(",
    "  supportedErrorRoutes: readonly GeneratedEntityErrorRouteOption[],",
    "): Field {",
    "  return {",
    "    key: \"errorRoutes\",",
    "    valueType: \"object\",",
    "    label: { en: \"Error routes\", nl: \"Foutpaden\" },",
    "    description: {",
    "      en: \"Select which backend errors should get their own output handle.\",",
    "      nl: \"Kies welke backend-fouten een eigen uitgang krijgen.\",",
    "    },",
    "    children: supportedErrorRoutes.map((option) => ({",
    "      key: option.id,",
    "      valueType: \"boolean\" as const,",
    "      label: { en: option.label.en, nl: option.label.nl },",
    "      description: { en: option.description.en, nl: option.description.nl },",
    "      render: { component: \"Checkbox\" },",
    "    })),",
    "    defaultValue: {},",
    "  };",
    "}",
    "",
    "/**",
    " * Normalizes a stored node config so `errorRoutes` is a Record<string, boolean>",
    " * of known IDs. Accepts both the legacy string[] shape and the current record",
    " * shape so existing seed data continues to load.",
    " */",
    "export function normalizeGeneratedEntityErrorRouteConfig(",
    "  config: Record<string, unknown>,",
    "  supportedErrorRoutes: readonly GeneratedEntityErrorRouteOption[],",
    "): Record<string, unknown> {",
    "  const supportedIds = supportedErrorRoutes.map((option) => option.id);",
    "  const normalized = normalizeSelection(",
    "    (config as { errorRoutes?: unknown }).errorRoutes,",
    "    supportedIds,",
    "  );",
    "  return { ...config, errorRoutes: normalized };",
    "}",
    "",
    "function getSelectedOptions(",
    "  config: Record<string, unknown>,",
    "  supportedErrorRoutes: readonly GeneratedEntityErrorRouteOption[],",
    "): GeneratedEntityErrorRouteOption[] {",
    "  const supportedIds = supportedErrorRoutes.map((option) => option.id);",
    "  const normalized = normalizeSelection(",
    "    (config as { errorRoutes?: unknown }).errorRoutes,",
    "    supportedIds,",
    "  );",
    "  return supportedErrorRoutes.filter((option) => normalized[option.id] === true);",
    "}",
    "",
    "/**",
    " * Output handles for non-list entity actions: only the success handle.",
    " * API/GraphQL failures fail the workflow globally (same model as ai.generateReply / router),",
    " * not separate \"Fout\" or per-code branches.",
    " */",
    "export function buildGeneratedEntityOutputHandles(",
    "  _config: Record<string, unknown>,",
    "  _supportedErrorRoutes: readonly GeneratedEntityErrorRouteOption[],",
    "): WorkflowNodeHandle[] {",
    "  return [{ id: DEFAULT_SUCCESS_HANDLE_ID, label: DEFAULT_SUCCESS_HANDLE_LABEL }];",
    "}",
    "",
    "/**",
    " * Output handles for list entity actions: semantic count routes.",
    " * Errors do not get dedicated ports — failures fail the workflow run.",
    " */",
    "export function buildGeneratedEntityListOutputHandles(",
    "  _config: Record<string, unknown>,",
    "  _supportedErrorRoutes: readonly GeneratedEntityErrorRouteOption[],",
    "): WorkflowNodeHandle[] {",
    "  return [",
    "    { id: LIST_NONE_HANDLE_ID, label: \"Geen resultaten\" },",
    "    { id: LIST_ONE_HANDLE_ID, label: \"Een resultaat\" },",
    "    { id: LIST_MANY_HANDLE_ID, label: \"Meerdere resultaten\" },",
    "  ];",
    "}",
    "",
    "/**",
    " * Historic API: workflows no longer expose error handles for entity nodes;",
    " * kept so older generated defs that reference this symbol still compile.",
    " */",
    "export function isGeneratedEntityErrorHandle(",
    "  _handleId: string | undefined,",
    "  _config: Record<string, unknown>,",
    "  _supportedErrorRoutes: readonly GeneratedEntityErrorRouteOption[],",
    "): boolean {",
    "  return false;",
    "}",
    "",
    "/**",
    " * Returns true when `handleId` is a semantic list-count success handle.",
    " * These handles return the node's own output fields rather than the",
    " * user-filtered output-parameter selection.",
    " */",
    "export function isGeneratedEntityListCountSuccessHandle(",
    "  handleId: string | undefined,",
    "): boolean {",
    "  return (",
    "    handleId === LIST_NONE_HANDLE_ID",
    "    || handleId === LIST_ONE_HANDLE_ID",
    "    || handleId === LIST_MANY_HANDLE_ID",
    "  );",
    "}",
    "",
  ].join("\n");
}
